// ===== Scorer v1: Parameter (nur hier ändern) =====
const MODEL = 'gemini-3.1-flash-lite';      // Hauptmodell (wie Employer-Scout v1.3.5)
const FALLBACK_MODEL = 'gemini-3.8-flash';  // Ersatz nach 3 Fehlversuchen
const TEMPERATURE = 0;
const WRITER_THRESHOLD = 75;                // ab diesem Score darf der Writer ein Anschreiben entwerfen
const MIN_SALARY = 0;     // eigenes Mindestgehalt eintragen                   // Euro brutto pro Jahr, Vollzeitäquivalent

// Kurzprofil OHNE Kontaktdaten (nur das geht an Gemini). Quelle: skills-evidence.md, scorer-criteria.md
const PROFILE = `Kurzprofil OHNE Name und Kontaktdaten hier eintragen: Zielrollen, Wohnort/Bezugspunkt fuer den Arbeitsweg, Berufserfahrung mit konkreten Aufgaben, Weiterbildung, Tools, was NICHT vorhanden ist (nur als Luecke nennen), Sprachen, Abschluss, Verfuegbarkeit, Mindestgehalt ${MIN_SALARY} Euro brutto/Jahr.`;

// Bewertungsregeln (bestätigt 2026-11-07, Ort/Sprache/Vertrieb präzisiert 2026-11-08)
const RULES = `Bewerte nach dem Aufgabenumfang (Scope), nicht nach dem Jobtitel.
Teilwerte: scope 0-50, skills 0-20, language 0-10, location 0-10, conditions 0-10.
- scope: Wie stark decken sich die Aufgaben der Anzeige mit der Erfahrung? Projektkoordination, Budget-/Kostenkontrolle, Leistungsnachweise, Dienstleistersteuerung, Reporting, Prozessoptimierung/Automatisierung = hoch. Reine Sekretariats-, Empfangs-, Kassen-, Payroll-, KYC-, Fraud- oder Store-Aufgaben = niedrig. Sind Vertrieb, Akquise oder Finanzierung durch Verkauf die Hauptverantwortung (auch wenn "Projektmanager" im Titel steht): scope höchstens 15.
- skills: geforderte Tools und Methoden, die laut Profil vorhanden sind. Fehlende Tools nur als Lücke, nicht erfinden.
- language: 10 wenn Deutsch C1 reicht ("sehr gute", "fließende", "verhandlungssichere" Deutschkenntnisse zählen als C1) oder Arbeitssprache Englisch; weniger nur, wenn ausdrücklich C2/Muttersprache verlangt wird oder viel gesprochenes Deutsch (Telefon, Präsentationen, Schulungen) Kern der Stelle ist.
- location: Bezugspunkt REFERENCE_POINT. 10, wenn das Büro höchstens ca. 7 km entfernt ist (Bezirke im Radius hier eintragen) oder die Stelle vollständig remote ist (100 % Homeoffice, egal wo). 0 und harter Ausschluss, wenn Präsenz oder Hybrid verlangt wird und das Büro weiter weg ist (z. B. Spandau, Marzahn, Reinickendorf, Potsdam, Teltow, Kleinmachnow). Steht im Text eine Zeile "Entfernung Büro – REFERENCE_POINT", diese Zahl verwenden. Adresse unklar: 5 Punkte und in open_questions "Büroadresse prüfen (max. 7 km vom REFERENCE_POINT)".
- conditions: Gehalt (sofern genannt) über Mindestgehalt, Festanstellung, Start passt (ab 03/2027 oder flexibel). Keine Angaben = 7. Liegt das genannte Gehalt (Vollzeit, Fixum) unter dem Mindestgehalt: höchstens 3.
Strafpunkte (penalties), nur wenn in der Anzeige klar gefordert, nicht bei "wünschenswert"/"idealerweise":
- Programmierung (Python/TypeScript o. ä.) als Kernaufgabe: -15
- Gesprochenes Deutsch als Kernaufgabe (Kundentelefonate, Präsentationen, Schulungen auf Deutsch): -15 bis -25 je nach Anteil
- Deutsch ausdrücklich "Muttersprache"/"muttersprachlich" oder C2 gefordert: -8 (NICHT bei "sehr gute", "fließende" oder "verhandlungssichere" Deutschkenntnisse)
- Technisches oder naturwissenschaftliches Studium gefordert (ohne "oder vergleichbare Erfahrung"): -5
- SAP/ERP als Kernanforderung: -10
- BWL-/Controlling-Studium zwingend gefordert: -5
- Kern der Anzeige sind Negativ-Themen (Empfang, Rezeption, Kasse, Fraud, KYC, Payroll, Store, Sekretariat, Büromanagement, Assistenz der Geschäftsführung): -30
Bonus: interne Rolle ohne Kundenkontakt: +5.
Harte Ausschlusskriterien (hard_exclusions), nur wenn als Anforderung formuliert: "5+ Jahre Berufserfahrung in Deutschland"; Personalverantwortung / Teamleitung; Büro mehr als ca. 7 km vom REFERENCE_POINT entfernt bei Präsenzpflicht oder Hybrid (nicht bei 100 % remote).
Kein Ausschluss, nur Lücke: fehlende Zertifikate (PMP, ITIL, PRINCE2), Zeitarbeit als Arbeitgeber, "3+ Jahre Erfahrung" ohne Bezug auf Deutschland (10+ Jahre Projektarbeit sind vorhanden).
Gehalt: steht eine Spanne in der Anzeige und ihr oberes Ende liegt unter ${MIN_SALARY} Euro, in open_questions "Gehalt unter Minimum" vermerken (kein Ausschluss). Fehlt das Gehalt: open_questions "Gehalt erfragen".`;

const f = $input.first().json;
const adText = String(f['Anzeigentext'] || '').trim();
if (adText.length < 200) throw new Error('Anzeigentext ist zu kurz (' + adText.length + ' Zeichen). Bitte den vollständigen Text der Stellenanzeige einfügen.');

return [{ json: {
  model: MODEL, fallback_model: FALLBACK_MODEL, temperature: TEMPERATURE,
  writer_threshold: WRITER_THRESHOLD, min_salary: MIN_SALARY,
  profile: PROFILE, rules: RULES,
  title: String(f['Stellentitel'] || '').trim(),
  employer: String(f['Arbeitgeber'] || '').trim(),
  url: String(f['Link zur Stelle'] || '').trim(),
  source: String(f['Gefunden über'] || 'Nischenportal'),
  ad_text: adText.slice(0, 20000),
} }];

// Baut den EINEN Gemini-Aufruf. Keine Kontaktdaten im Prompt.
const p = $input.first().json;

const prompt = `Du bist ein nüchterner Bewerbungs-Scorer. Du vergleichst eine Stellenanzeige mit einem Kandidatenprofil und bewertest die Passung nach festen Regeln. Du erfindest keine Fähigkeiten, die nicht im Profil stehen. Antworte ausschließlich als JSON nach dem vorgegebenen Schema, alle Texte auf Deutsch, kurz und konkret.

=== KANDIDATENPROFIL ===
${p.profile}

=== BEWERTUNGSREGELN ===
${p.rules}

=== STELLENANZEIGE ===
Titel: ${p.title || '(nicht angegeben)'}
Arbeitgeber: ${p.employer || '(nicht angegeben)'}
Text:
${p.ad_text}

=== AUSGABE ===
- scope, skills, language, location, conditions: ganze Zahlen in den genannten Bereichen.
- penalties: Liste von {reason, points} mit negativen Zahlen (points), nur Regeln aus der Liste, nur wenn in der Anzeige klar gefordert. Leere Liste, wenn nichts zutrifft.
- bonus_internal: true nur bei interner Rolle ohne Kundenkontakt.
- hard_exclusions: Liste kurzer deutscher Sätze mit Zitat aus der Anzeige; leer, wenn keins zutrifft.
- scope_summary: 3-6 Zeilen, die Hauptaufgaben der Stelle in eigenen Worten.
- matches: 3-8 Stichpunkte, was aus dem Profil zu den Aufgaben passt (mit Bezug auf die konkrete Erfahrung).
- gaps: Stichpunkte, was gefordert ist und im Profil fehlt oder schwach ist. Nichts beschönigen.
- open_questions: offene Punkte für die Kandidatin (Gehalt, Start, Arbeitsort, Teilzeit, unklare Anforderungen).
- work_mode: "Remote", "Hybrid", "Vor Ort" oder null.
- salary_in_ad: genannte Gehaltsangabe als Text oder null.`;

const schema = {
  type: 'OBJECT',
  properties: {
    scope: { type: 'INTEGER' }, skills: { type: 'INTEGER' }, language: { type: 'INTEGER' },
    location: { type: 'INTEGER' }, conditions: { type: 'INTEGER' },
    penalties: { type: 'ARRAY', items: { type: 'OBJECT', properties: { reason: { type: 'STRING' }, points: { type: 'INTEGER' } }, required: ['reason', 'points'] } },
    bonus_internal: { type: 'BOOLEAN' },
    hard_exclusions: { type: 'ARRAY', items: { type: 'STRING' } },
    scope_summary: { type: 'STRING' },
    matches: { type: 'ARRAY', items: { type: 'STRING' } },
    gaps: { type: 'ARRAY', items: { type: 'STRING' } },
    open_questions: { type: 'ARRAY', items: { type: 'STRING' } },
    work_mode: { type: 'STRING', nullable: true, enum: ['Remote', 'Hybrid', 'Vor Ort'] },
    salary_in_ad: { type: 'STRING', nullable: true },
  },
  required: ['scope', 'skills', 'language', 'location', 'conditions', 'penalties', 'bonus_internal', 'hard_exclusions', 'scope_summary', 'matches', 'gaps', 'open_questions', 'work_mode', 'salary_in_ad'],
};

const body = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { temperature: p.temperature, maxOutputTokens: 8192, responseMimeType: 'application/json', responseSchema: schema },
};
return [{ json: { body } }];

// Gemini-Antwort lesen, Score deterministisch berechnen, Airtable-Datensatz bauen.
const p = $('Parameter').first().json;
const r = $input.first().json;
let fb = false;
try { fb = $('Gemini Ersatz').isExecuted; } catch (e) { fb = false; }

if (r.error) throw new Error('Gemini-Fehler: ' + JSON.stringify(r.error).slice(0, 500));
const cand = (r.candidates || [])[0];
if (!cand) throw new Error('Gemini hat keine Antwort geliefert: ' + JSON.stringify(r).slice(0, 500));
const text = ((cand.content || {}).parts || []).map(x => x.text || '').join('').trim();
let d;
try { d = JSON.parse(text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '')); }
catch (e) { throw new Error(`Antwort ist kein gültiges JSON (finishReason: ${cand.finishReason}). Anfang: ${text.slice(0, 300)}`); }

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, Math.round(Number(v) || 0)));
const parts = {
  scope: clamp(d.scope, 0, 50), skills: clamp(d.skills, 0, 20), language: clamp(d.language, 0, 10),
  location: clamp(d.location, 0, 10), conditions: clamp(d.conditions, 0, 10),
};
const base = parts.scope + parts.skills + parts.language + parts.location + parts.conditions;

// Strafpunkte: nur negative Werte, jede einzelne auf -30 begrenzt, Summe auf -60
const penalties = (Array.isArray(d.penalties) ? d.penalties : [])
  .map(x => ({ reason: String((x && x.reason) || '').trim(), points: clamp(-Math.abs((x && x.points) || 0), -30, 0) }))
  .filter(x => x.reason && x.points < 0);
let penaltySum = Math.max(-60, penalties.reduce((s, x) => s + x.points, 0));
const bonus = d.bonus_internal === true ? 5 : 0;
const hard = (Array.isArray(d.hard_exclusions) ? d.hard_exclusions : []).map(s => String(s).trim()).filter(Boolean);

let score = clamp(base + penaltySum + bonus, 0, 100);
const excluded = hard.length > 0;
const writerOk = !excluded && score >= p.writer_threshold;

const list = a => (Array.isArray(a) ? a : []).map(s => '- ' + String(s).trim()).filter(s => s.length > 2).join('\n');
const today = $now.toFormat('yyyy-MM-dd');
const modelUsed = r.modelVersion || (fb ? p.fallback_model : p.model);

const hardText = excluded
  ? 'AUSSCHLUSS:\n' + list(hard)
  : 'Kein hartes Ausschlusskriterium erkannt.';
const calc = [
  `Scope ${parts.scope}/50, Skills ${parts.skills}/20, Sprache ${parts.language}/10, Ort ${parts.location}/10, Bedingungen ${parts.conditions}/10 = ${base}`,
  penalties.length ? 'Strafpunkte: ' + penalties.map(x => `${x.points} (${x.reason})`).join('; ') : 'Strafpunkte: keine',
  bonus ? 'Bonus interne Rolle: +5' : null,
  `Score: ${score}` + (excluded ? ' (Ausschluss, Writer gesperrt)' : writerOk ? ` (>= ${p.writer_threshold}: Writer darf entwerfen)` : ` (< ${p.writer_threshold}: kein Anschreiben)`),
  d.work_mode ? `Arbeitsmodus laut Anzeige: ${d.work_mode}` : 'Arbeitsmodus laut Anzeige: unklar',
  d.salary_in_ad ? `Gehalt laut Anzeige: ${d.salary_in_ad}` : null,
  p.employer ? `Arbeitgeber: ${p.employer}` : null,
  `Scorer v1.2, ${today}, Modell ${modelUsed}${fb ? ' (Ersatzmodell)' : ''}`,
].filter(Boolean).join('\n');

const fields = {
  fldvi9NOQkjarh6Xp: [p.title || 'Stelle ohne Titel', p.employer].filter(Boolean).join(' – '),  // Stellentitel
  fld2I3y1rPj2PLr5G: /^https?:\/\//i.test(p.url) ? p.url : null,   // Link zur Stelle
  fld67zsuzjVMWlHj4: p.source,                                       // Gefunden über
  fldF286BWjQsP97ZU: String(d.scope_summary || '').trim() || null,  // Scope
  fldHbj2xOfzOGlFCL: score,                                          // Score (0 bis 100)
  fldDJXhcgXbVanYcF: list(d.matches) || null,                        // Treffer
  fldEWzhj9RXDUveLY: list(d.gaps) || null,                           // Lücken
  fldgFDKMAUQiY9utM: hardText,                                       // Harte Kriterien (Risiko)
  fldtvWymZSuRBDJYc: excluded ? 'Nicht beworben' : 'Bewertet',       // Status
  fldGLAKchtHtA6nGP: today,                                          // Entdeckt am
  fldSB3KbrVVJhGRBh: list(d.open_questions) || null,                 // Offene Fragen
  fldoRHnPAxTlxXJkQ: calc,                                           // Notizen
};
for (const k of Object.keys(fields)) if (fields[k] === null || fields[k] === undefined) delete fields[k];

return [{ json: { records: [{ fields }], _result: { score, excluded, writerOk, parts, penalties, bonus, hard, model: modelUsed, usage: r.usageMetadata || null, finishReason: cand.finishReason || null } } }];

// Zusammenfassung des Laufs (Ausgabe für das Formular und für Tests).
const p = $('Parameter').first().json;
const res = $('Bewerten').first().json._result;
const save = $input.first().json;
const saved = (save.records || [])[0];
const err = save.error ? JSON.stringify(save.error).slice(0, 300) : null;

return [{ json: {
  'Stelle': [p.title, p.employer].filter(Boolean).join(' – '),
  'Score': res.score,
  'Teilwerte': res.parts,
  'Strafpunkte': res.penalties,
  'Bonus': res.bonus,
  'Harter Ausschluss': res.hard,
  ['Writer freigegeben (>= ' + p.writer_threshold + ')']: res.writerOk,
  'Airtable-Datensatz': saved ? saved.id : null,
  'Speicherfehler': err,
  'Modell': res.model,
  'Gemini-Tokens': res.usage ? res.usage.totalTokenCount : null,
  'Gemini-Abbruchgrund': res.finishReason,
} }];
